#!/usr/bin/env bash
# SessionStart addition — STRIDE methodology framing checklist.
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
core_role_directive $'YOU DECIDE: frame scope first — where does this spec touch a trust boundary, authentication, or sensitive-data handling? Name those touchpoints before enumerating threats' $'USE WHEN: STRIDE is the standing default methodology for threat enumeration unless a documented reason routes elsewhere' $'PRODUCES: precondition order for the record: asset-inventory -> trust-boundary-map -> stride-table. Each element must exist, in that order, before the next' $'HAND-OFF: judgment criterion for specs with no trust boundary in view: BOUNDARY_CASE (a boundary exists but is not yet named — keep working the spec until it is) vs HAND_OFF (no trust boundary applies to this spec at all — hand off rather than force a STRIDE table where none belongs)'
